<script setup lang="ts">
import { exportCsv } from '~/lib/exportCsv'
const props = defineProps<{ report: any }>()
const { data: company } = useAppSettings()
const compare = ref(false), hideZero = ref(true), collapsed = ref<string[]>([])
const current = computed(() => props.report.balance_sheet)
const previous = computed(() => props.report.comparison)
const money = (n: number) => n < 0 ? `(${fmtRp(-n)})` : fmtRp(n)
const date = (s: string) => new Date(`${s}T12:00:00`).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })
type Row = { id: string; name: string; level: number; type: string; value: number; prior: number; group?: string; account?: string }
const allRows = computed<Row[]>(() => {
  const rows: Row[] = []
  const amount = (snapshot: any, codes: string[]) => snapshot.accounts.filter((a: any) => codes.includes(a.code)).reduce((s: number, a: any) => s + a.balance, 0)
  const total = (id: string, name: string, key: string) => rows.push({ id, name, level: 0, type: 'total', value: current.value.totals[key], prior: previous.value.totals[key] })
  const section = (id: string, name: string) => rows.push({ id, name, level: 0, type: 'section', value: 0, prior: 0 })
  const group = (id: string, name: string, codes: string[]) => {
    rows.push({ id, name, level: 1, type: 'group', value: amount(current.value, codes), prior: amount(previous.value, codes) })
    for (const code of codes) { const a = current.value.accounts.find((a: any) => a.code === code); rows.push({ id: code, name: a.name, account: code, group: id, level: 2, type: 'account', value: a.balance, prior: amount(previous.value, [code]) }) }
  }
  section('assets', 'Aset'); group('current', 'Aset lancar', ['1101', '1102', '1103', '1104']); group('fixed', 'Aset tetap', ['1201', '1202']); total('assets-total', 'Total aset', 'asset')
  section('liabilities', 'Liabilitas'); group('payable', 'Utang usaha & kewajiban telekomunikasi', ['2101', '2102', '2103']); group('loans', 'Pinjaman', ['2104']); total('liability-total', 'Total liabilitas', 'liability')
  section('equity', 'Ekuitas'); group('capital', 'Modal & saldo laba', ['3101', '3102'])
  for (const [id, name, key] of [['profit_prior', 'Laba ditahan dari tahun sebelumnya', 'prior_profit'], ['profit_current', 'Laba / rugi tahun berjalan', 'current_profit']]) rows.push({ id, name, level: 1, type: 'account', account: id, value: current.value[key], prior: previous.value[key] })
  total('equity-total', 'Total ekuitas', 'equity')
  rows.push({ id: 'balance-total', name: 'Total liabilitas dan ekuitas', level: 0, type: 'grand', value: current.value.totals.liability + current.value.totals.equity, prior: previous.value.totals.liability + previous.value.totals.equity })
  return rows
})
const visible = computed(() => allRows.value.filter(row => row.type !== 'account' || ((!hideZero.value || row.value !== 0 || compare.value && row.prior !== 0) && !collapsed.value.includes(row.group || ''))))
function toggle(id: string) { collapsed.value = collapsed.value.includes(id) ? collapsed.value.filter(g => g !== id) : [...collapsed.value, id] }
const detail = ref<any>(null), detailOpen = ref(false), detailTitle = ref(''), detailLoading = ref(false), detailError = ref('')
const pages = usePagination(() => detail.value?.rows || [])
let request = 0
async function openAccount(row: Row, prior = false) {
  const id = ++request; detailOpen.value = true; detail.value = null; detailTitle.value = row.name; detailLoading.value = true; detailError.value = ''
  try { const d = await api(`/api/pembukuan/account?account=${row.account}&to=${prior ? previous.value.date : current.value.date}`); if (id === request) { detail.value = d; pages.page = 1 } }
  catch (e) { if (id === request) detailError.value = errMsg(e) } finally { if (id === request) detailLoading.value = false }
}
function exportReport() { exportCsv(`neraca-${current.value.date}.csv`, [[company.value?.nama_isp || '', 'Neraca'], ['Posisi', current.value.date, ...(compare.value ? [previous.value.date] : [])], ['Akun', 'Nama akun', 'Saldo', ...(compare.value ? ['Saldo pembanding'] : [])], ...allRows.value.map(r => [r.account || '', r.name, r.type === 'section' ? '' : r.value, ...(compare.value ? [r.type === 'section' ? '' : r.prior] : [])])]) }
function printReport() {
  const win = window.open('', '_blank'); if (!win) { toast('Izinkan jendela cetak di browser.', 'error'); return }; win.opener = null
  const e = (s: any) => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]!))
  win.document.write(`<!doctype html><html lang="id"><head><title>Neraca ${e(current.value.date)}</title><style>body{font:12px/1.5 Arial;color:#16304d;margin:35px}h1{font-size:21px;margin:6px 0}header{text-align:center;margin-bottom:24px}table{width:100%;border-collapse:collapse}td,th{padding:7px 9px;text-align:right}td:first-child,th:first-child{text-align:left}.section{font-weight:bold;background:#eef3f9}.total,.grand{font-weight:bold;border-top:1px solid #b6c5d5}.grand{border-bottom:3px double #16304d}.group{font-weight:bold}tr{break-inside:avoid}@page{size:A4;margin:12mm}</style></head><body><header><b>${e(company.value?.nama_isp)}</b><h1>Neraca</h1><div>Per ${e(date(current.value.date))}</div></header><table><thead><tr><th>Akun</th><th>${e(date(current.value.date))}</th>${compare.value ? `<th>${e(date(previous.value.date))}</th>` : ''}</tr></thead><tbody>${allRows.value.filter(r => r.type !== 'account' || !hideZero.value || r.value !== 0 || compare.value && r.prior !== 0).map(r => `<tr class="${r.type}"><td style="padding-left:${9 + r.level * 14}px">${e(r.name)}</td><td>${r.type === 'section' ? '' : e(money(r.value))}</td>${compare.value ? `<td>${r.type === 'section' ? '' : e(money(r.prior))}</td>` : ''}</tr>`).join('')}</tbody></table><p>Pembukuan internal. Mulai pembukuan: ${e(props.report.start_date || 'Belum ditetapkan')}. ${props.report.pending ? `${props.report.pending} perubahan tagihan belum dibukukan.` : ''}</p></body></html>`)
  win.document.close(); win.focus(); win.print()
}
</script>
<template>
  <section class="card balance-report" aria-label="Laporan neraca">
    <div class="balance-controls"><div><label><input v-model="hideZero" type="checkbox"> Sembunyikan saldo nol</label><label><input v-model="compare" type="checkbox"> Bandingkan bulan sebelumnya</label></div><div class="op-actions"><button class="btn btn-sec btn-sm" @click="exportReport">Ekspor CSV</button><button class="btn btn-sec btn-sm" @click="printReport"><Ico name="printer" :size="14" /> Cetak / PDF</button></div></div>
    <header class="balance-heading"><img src="/branding/altelmatara-network.png" alt="ALTELMATARA NETWORK"><p>{{ company?.nama_isp }}</p><h2>Neraca</h2><span>Per {{ date(current.date) }}</span><small>Dalam rupiah</small></header>
    <p v-if="compare" class="balance-swipe">Geser laporan ke samping untuk melihat kolom pembanding.</p><div class="balance-scroll"><div class="balance-lines" :class="{ compare }"><div class="balance-columns"><span>Nama akun</span><span>{{ date(current.date) }}</span><span v-if="compare">{{ date(previous.date) }}</span></div>
      <div v-for="row in visible" :key="row.id" class="balance-line" :class="row.type" :style="{ '--indent': `${row.level * 20}px` }">
        <button v-if="row.type === 'group'" class="balance-label group-toggle" :aria-expanded="!collapsed.includes(row.id)" @click="toggle(row.id)"><span aria-hidden="true">{{ collapsed.includes(row.id) ? '+' : '−' }}</span>{{ row.name }}</button>
        <span v-else class="balance-label"><small v-if="row.account && !row.account.startsWith('profit')">{{ row.account }}</small>{{ row.name }}</span>
        <template v-if="row.type !== 'section'"><button v-if="row.account" class="balance-amount" :aria-label="`Rincian ${row.name} per ${current.date}`" @click="openAccount(row)">{{ money(row.value) }}</button><b v-else>{{ money(row.value) }}</b><template v-if="compare"><button v-if="row.account" class="balance-amount" :aria-label="`Rincian pembanding ${row.name}`" @click="openAccount(row, true)">{{ money(row.prior) }}</button><b v-else>{{ money(row.prior) }}</b></template></template>
      </div>
    </div></div>
    <footer class="balance-footer"><span :class="{ 'balance-error': current.totals.difference !== 0 }">{{ current.totals.difference === 0 ? 'Aset = liabilitas + ekuitas' : `Selisih ${money(current.totals.difference)}` }}</span><p>Nilai biru membuka rincian jurnal. Laba tahun berjalan dihitung sejak 1 Januari. Pinjaman belum dipisahkan menurut jatuh tempo.</p></footer>
  </section>
  <UiModal :open="detailOpen" :title="detailTitle" wide @close="detailOpen = false; ++request">
    <div v-if="detailLoading" class="empty">Memuat rincian akun…</div><p v-else-if="detailError" class="op-note op-warning" role="alert">{{ detailError }}</p>
    <template v-else-if="detail"><div class="op-total"><span>Saldo per {{ date(detail.to) }}</span><b>{{ money(detail.balance) }}</b></div><div class="table-wrap"><table class="tbl"><thead><tr><th>Tanggal / jurnal</th><th>Uraian</th><th class="num">Debit</th><th class="num">Kredit</th><th class="num">Saldo</th></tr></thead><tbody><tr v-for="(r,i) in pages.rows" :key="`${r.id}-${i}`"><td>{{ r.date }}<small class="cell-sub">JRN-{{ r.id }} · {{ r.account }}</small></td><td>{{ r.description }}<div class="cell-sub">{{ r.reference }}</div></td><td class="num">{{ money(r.debit) }}</td><td class="num">{{ money(r.credit) }}</td><td class="num">{{ money(r.balance) }}</td></tr><tr v-if="!pages.total"><td colspan="5" class="empty">Belum ada transaksi untuk akun ini.</td></tr></tbody></table></div><TablePagination v-model:page="pages.page" v-model:page-size="pages.pageSize" :total="pages.total" label="rincian akun" /></template>
  </UiModal>
</template>
<style scoped>
.balance-swipe{display:none}.balance-report{margin:0 auto;overflow:hidden}.balance-controls{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 22px;border-bottom:1px solid #e2e9f1;background:#fafcfe}.balance-controls>div:first-child{display:flex;gap:20px;flex-wrap:wrap}.balance-controls label{font-size:12px;display:flex;align-items:center;gap:7px;color:#4d627c}.balance-controls input{accent-color:#195fd1}.balance-heading{padding:38px 24px 28px;text-align:center}.balance-heading img{width:200px;max-width:65%;height:auto;margin-bottom:15px}.balance-heading p{font-weight:600;font-size:14px;color:#233e5c;margin:0}.balance-heading h2{font-size:26px;letter-spacing:-.7px;margin:9px 0;color:#142b48}.balance-heading span{display:block;color:#526c86;font-size:13px}.balance-heading small{display:block;margin-top:7px;font-size:11px;color:#7e8ea2}.balance-scroll{overflow-x:auto;padding:0 30px}.balance-lines{min-width:520px}.balance-columns,.balance-line{display:grid;grid-template-columns:minmax(300px,1fr) 180px;align-items:center;column-gap:16px}.compare .balance-columns,.compare .balance-line{grid-template-columns:minmax(300px,1fr) 180px 180px}.balance-lines.compare{min-width:730px}.balance-columns{padding:12px 10px;color:#72839a;border-bottom:1px solid #cad7e5;font-size:11px}.balance-columns>span:not(:first-child){text-align:right}.balance-line{padding:10px;font-size:13px;min-height:39px}.balance-line .balance-label{padding-left:var(--indent);display:flex;align-items:center;gap:12px}.balance-label small{font-size:10px;color:#90a0b1;min-width:27px}.balance-line>b{text-align:right;font-size:13px;font-weight:600;white-space:nowrap;font-variant-numeric:tabular-nums}.balance-line.section{margin-top:16px;background:#edf3fa;color:#203f63;font-weight:700;padding:12px 10px;min-height:42px}.balance-line.group{font-weight:600;color:#385472;padding-top:15px}.group-toggle{font:inherit;border:0;background:none;text-align:left;color:inherit;cursor:pointer;min-height:24px}.group-toggle span{font-size:14px;min-width:14px;color:#7991ac}.balance-amount{border:0;background:none;text-align:right;color:#195fd1;font:inherit;cursor:pointer;font-variant-numeric:tabular-nums;white-space:nowrap;padding:3px 0}.balance-amount:hover{text-decoration:underline}.balance-line.account:hover{background:#f8fbff}.balance-line.total{border-top:1px solid #cfdae7;margin-top:7px;font-weight:700;padding:14px 10px}.balance-line.grand{margin-top:10px;border-top:1px solid #92a9c2;border-bottom:3px double #92a9c2;padding:16px 10px;font-weight:700}.balance-footer{padding:20px 40px 30px}.balance-footer>span{font-size:12px;color:#207058;font-weight:600}.balance-footer .balance-error{color:#a72c38}.balance-footer p{color:#8391a3;font-size:11px;margin:7px 0 0;max-width:85ch}@media(max-width:700px){.balance-controls{align-items:flex-start;flex-direction:column;padding:16px}.balance-controls>div:first-child{gap:12px}.balance-scroll{padding:0 12px}.balance-heading{padding:26px 16px}.balance-footer{padding:20px}.balance-lines:not(.compare){min-width:0}.balance-lines:not(.compare) .balance-columns,.balance-lines:not(.compare) .balance-line{grid-template-columns:minmax(0,1fr) 120px;column-gap:8px}.balance-line{padding:10px 6px;font-size:12px}.balance-line .balance-label{padding-left:calc(var(--indent) * .4);gap:5px}.balance-label small{display:none}.balance-line>b{font-size:12px}.balance-columns{padding:10px 6px;font-size:10px}.balance-amount{font-size:12px}.balance-swipe{display:block!important;font-size:11px;color:#7589a0;padding:0 18px 12px;margin:0}}
</style>
